// This is start of the header guard. By convention, we use the name of the header file.
#ifndef MAKE_DOMAIN_H
#define MAKE_DOMAIN_H

#define CGAL_MESH_3_VERBOSE
#include <fstream>
#include <vector>
#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <CGAL/Mesh_triangulation_3.h>
#include <CGAL/Mesh_complex_3_in_triangulation_3.h>
#include <CGAL/Mesh_criteria_3.h>
#include <CGAL/Mesh_constant_domain_field_3.h>
#include <CGAL/Labeled_image_mesh_domain_3.h>
#include <CGAL/Mesh_domain_with_polyline_features_3.h>
#include <CGAL/make_mesh_3.h>
#include <CGAL/Image_3.h>
#include <map>
// Domain
typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Mesh_domain_with_polyline_features_3<
    CGAL::Labeled_image_mesh_domain_3<CGAL::Image_3,K> >    Mesh_domain;

typedef K::Point_3 Point3d;

// Polyline features that want to preserve
typedef std::vector<Point3d> Polyline;


// Triangulation
#ifdef CGAL_CONCURRENT_MESH_3
  typedef CGAL::Mesh_triangulation_3<
    Mesh_domain,
    CGAL::Kernel_traits<Mesh_domain>::Kernel, // Same as sequential
    CGAL::Parallel_tag                        // Tag to activate parallelism
  >::type Tr;
#else
  typedef CGAL::Mesh_triangulation_3<Mesh_domain>::type Tr;
#endif

typedef CGAL::Mesh_complex_3_in_triangulation_3<
    Tr,Mesh_domain::Corner_index,Mesh_domain::Curve_segment_index> C3t3;
// Criteria
typedef CGAL::Mesh_criteria_3<Tr> Mesh_criteria;
typedef CGAL::Mesh_constant_domain_field_3<Mesh_domain::R,
                                           Mesh_domain::Index> Sizing_field;

// User defined header files
#include "cgal_subdomain.h"

// System namespace
using namespace std;
using namespace CGAL::parameters;

class cgal_domain{
public:
	cgal_domain();
	~cgal_domain();
	// initialize domain
	void initialize();

	// Set domain outer box: bottom left coordinate, length and
	// minimum discretization in each direction
	void setDomainBox(const double x0, const double y0, const double z0,
			const double xl, const double yl, const double zl,
			const double dx, const double dy, const double dz);

	// Set domain mesh criteria
	void setDomainCriteria(const double edgeSize, const double facetAngle,
			const double facetSize, const double facetDistance,
			const double cellRadiusEdgeRatio, const double globalSize);

	// Make and output the domain information to inr image file
	void makeOutputImage(const std::string strfile);

	// Optimization parameters of Lloyd
	void setOptParametersLloyd(const int maxIteration, const double timeLimit);

	// Optimization parameters of Exude
	void setOptParametersExude(const double sliverBound, const double timeLimit);

	// Optimization parameters of Perturb
	void setOptParametersPerturb(const double silverBound, const double timeLimit);

	// Make and output the mesh based on inr image file
	void makeOutputMesh(const std::string strImageFile,
			const std::string strMeshFile, const std::string strMeshFormat);

	// Add subdomain by off file
	int addSubDomain(const int id, const std::string name, const double size,
			const std::string strDomainOffFile);

	// Add polyline feature
	void addFeaturePolyline(const Polyline polyline);

	// Get number of subdomains
	int numSubDomains();

	// Get subdomain by domain id
	cgal_subdomain getSubDomain(const int id);

	// Set domain data value according the subdomain information
	void setDomainDataValue();

protected:

private:
	// Clear subdomains
	void clearSubDomains();

	// Clear features
	void clearDomainFeatures();

	// Set default image parameters
	void setImageDefaultParameters();

	// Set meshing default parameters
	void setMeshingDefaultParameters();

	//Global variable that can be accessed from other modules.
	//
	//Discretization variables
	//
	//x coordinate
	double xcoord;
	//y coordinate
	double ycoord;
	//z coordinate
	double zcoord;
	//total length in x direction
	double xlen;
	//total length in y direction
	double ylen;
	//total length in z direction
	double zlen;
	//minimum discretization (vertex size) in x direction
	double dxmin;
	//minimum discretization (vertex size) in y direction
	double dymin;
	//minimum discretization (vertex size) in z direction
	double dzmin;
	//number of discretization in x direction
	int xdim;
	//number of discretization in y direction
	int ydim;
	//number of discretization in z direction
	int zdim;
	// number of scalar per voxel (1 = scalar image, 3 = 3D image of vectors)
	int vdim;
	// Dimension
	int ndim;
	//data type float, signed fixed, or unsigned fixed
	std::string datatype;
	//data pixsize, 8, 16, 32, or 64
	std::string pixsize;
	//scale value, not used in this program
	std::string datascale;
	//CPU type, decm, alpha, pc, sun, sgi,
	//little endianness : decm, alpha, pc; big endianness :sun, sgi
	std::string cpu;
	// store region labels, need initialization by the domain box value
	char *data;

	//
	//Subdomain variables
	//
	// Number of subdomains
	int num_subdomains;
	// Subdomain list
	std::list<cgal_subdomain> subdomains;

	//
	//Polyline features that want to preserve
	//
	std::list<Polyline>	 domain_features;

	//
	//Mesh criteria
	//   parameter edge_size: a scalar field (resp. a constant) providing a space varying (resp. a uniform)
	//                        upper bound for the lengths of curve segment edges. This parameter has to be
	//                        set to a positive value when 1-dimensional features protection is used.
	double criteriaEdgeSize;
	//
	//   parameter facet_angle: a lower bound for the angles (in degrees) of the surface mesh facets.
	double criteriaFacetAngle;
	//   parameter facet_size: a scalar field (resp. a constant) describing a space varying (resp. a uniform)
	//                         upper-bound or for the radii of the surface Delaunay balls.
	double criteriaFacetSize;
	//   parameter facet_distance: a scalar field (resp. a constant) describing a space varying (resp. a uniform)
	//                             upper bound for the same distance.
	double criteriaFacetDistance;
	//   parameter cell_radius_edge_ratio: an upper bound for the radius-edge ratio of the mesh tetrahedra.
	double criteriaCellRadiusEdgeRatio;
	//   parameter cell_size: a scalar field (resp. a constant) describing a space varying (resp. a uniform)
	//                        upper-bound for the circumradii of the mesh tetrahedra.
	double critieriaGlobalSize;

	//
	//Output mesh information
	//
	//Number of vertices
	int mesh_vertices_counter;

	//Number of edges
	int mesh_edges_counter;

	//Number of faces
	int mesh_faces_counter;

	//Number of surface face counter
	int mesh_surface_faces_counter;

	//Number of cells
	int mesh_cells_counter;

	//
	//Mesh optimization parameters
	//
	bool b_opt_lloyd;
	bool b_opt_exude;
	bool b_opt_perturb;
	int maxIterationLloyd;
	double timeLimitLloyd;
	double sliverBoundExude;
	double timeLimitExude;
	double sliverBoundPerturb;
	double timeLimitPerturb;

};

// This is the end of the header guard
#endif

